<?php
namespace App\Services;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class Cart {
 public static function add(Request $r):void {
  $v=$r->validate(['product_id'=>'required|integer','variation_id'=>'nullable|integer','quantity'=>'required|integer|between:1,99999']);
  DB::transaction(function()use($v){DB::table('users')->where('id',auth()->id())->lockForUpdate()->first();$p=Commerce::catalog(DB::table('products'))->where('products.id',$v['product_id'])->first();abort_unless($p,404);if(DB::table('seller_businesses')->where('user_id',$p->seller_id)->where('vacation',1)->exists())Support::fail('product','Store is on vacation.');$var=isset($v['variation_id'])?DB::table('product_variations')->where('id',$v['variation_id'])->where('product_id',$p->id)->whereNull('deleted_at')->first():null;if(isset($v['variation_id'])&&!$var)Support::fail('variation_id','Invalid variation.');if(!$var&&DB::table('product_variations')->where('product_id',$p->id)->whereNull('deleted_at')->exists())Support::fail('variation_id','Select a variation.');$q=DB::table('cart_items')->where('buyer_id',auth()->id())->where('product_id',$p->id)->where('variation_id',$var->id??null);$old=$q->orderBy('id')->get();$quantity=$old->sum('quantity')+$v['quantity'];if($quantity>min($p->stock,$var->stock??$p->stock,99999))Support::fail('quantity','Requested quantity exceeds available stock.');if($old->isEmpty())DB::table('cart_items')->insert(['buyer_id'=>auth()->id(),'product_id'=>$p->id,'variation_id'=>$var->id??null,'quantity'=>$quantity,'created_at'=>now(),'updated_at'=>now()]);else {DB::table('cart_items')->where('id',$old[0]->id)->update(['quantity'=>$quantity,'updated_at'=>now()]);DB::table('cart_items')->whereIn('id',$old->skip(1)->pluck('id'))->delete();}});
 }
 public static function update(Request $r,int $id):void {$v=$r->validate(['quantity'=>'required|integer|between:1,99999']);$row=DB::table('cart_items')->where('id',$id)->where('buyer_id',auth()->id())->first();abort_unless($row,404);$p=DB::table('products')->find($row->product_id);$var=$row->variation_id?DB::table('product_variations')->find($row->variation_id):null;if(!$p||$v['quantity']>min($p->stock,$var->stock??$p->stock))Support::fail('quantity','Requested quantity exceeds stock.');DB::table('cart_items')->where('id',$id)->update($v+['updated_at'=>now()]);}
 public static function profile(Request $r):void {$v=$r->validate(['name'=>['required','string','min:2','max:101',"regex:/^[\p{L}\p{M} .'-]+$/u"],'phone'=>'required|string','profile_photo'=>'nullable|image|mimes:jpg,jpeg,png|extensions:jpg,jpeg,png|max:5120']);$u=auth()->user();$phone=Registration::normalizePhone($v['phone']);if($phone!==Registration::normalizePhone((string)$u->phone))Support::fail('phone','Change your phone through Account verification.');$data=['name'=>$v['name'],'updated_at'=>now()];
 if($r->hasFile('profile_photo')){abort_unless(in_array($u->role,['buyer','seller','rider','sorting_center'],true),403);$data['profile_photo']=$r->file('profile_photo')->store('profiles','public');}
 try{DB::table('users')->where('id',$u->id)->update($data);}catch(\Throwable $ex){if(isset($data['profile_photo']))\Illuminate\Support\Facades\Storage::disk('public')->delete($data['profile_photo']);throw $ex;}
 if(isset($data['profile_photo'])&&$u->profile_photo)\Illuminate\Support\Facades\Storage::disk('public')->delete($u->profile_photo);}
}
